package org.humanjourney.core.geography;
import java.util.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.RegistryFriendlyByteBuf;
import org.humanjourney.core.npc.context.*;
import org.humanjourney.core.geography.map.*;
import org.humanjourney.core.geography.map.client.*;
import org.humanjourney.core.mapfeature.FeatureGeometry;
class GeographyCapacityTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;static GeographyCapacityBenchmarkTest.Review review;
 static final Set<String> BLOCKERS=Set.of("baltic_archipelagos__northern_europe","bothnian_coast","central_swedish_lowland","finnish_lakeland","karelian_lake_country","norrland_forest_uplands","northern_fennoscandia","norwegian_fjord_coast","scandinavian_mountains","southern_finnish_coastal_lowlands");
 static final UUID SESSION=UUID.fromString("00000000-0000-0000-0000-000000000151");
 @BeforeAll static void bootstrap()throws Exception{loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();review=new GeographyCapacityBenchmarkTest.Review();}
 @AfterAll static void close(){loader.close();}
 static MapPackets.Header h(long sequence){return new MapPackets.Header(SESSION,sequence,sequence,sequence,sequence);}
 static MapPackets.Frame wire(MapPackets.Frame frame){var b=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY));try{MapPackets.CODEC.encode(b,frame);assertTrue(b.readableBytes()<=48*1024);var copy=MapPackets.CODEC.decode(b);assertEquals(frame,copy);return copy;}finally{b.release();}}
 static MapArea synthetic(boolean holes){var data=holes?GeographyCapacityBenchmarkTest.fixture(511,32):GeographyV2Test.resource(2,"synthetic",true,GeographyV2Test.geometry(512));var geo=NpcGeography.parse(List.of(data),Set.of("era_0"));return new MapProjection.Factory(geo,"era_0").project(new DiscoveryLedger.Snapshot(Set.of(),Set.of("synthetic"),1)).areas().values().iterator().next();}
 @Test void maximumManyHoleAndMultipartAreasPassJsonNativeWireAndAtomicReconstruction(){for(boolean holes:List.of(false,true)){var area=synthetic(holes);assertEquals(512,area.shape().ringCount());assertEquals(16384,area.shape().vertexCount());var frames=MapPackets.frames(h(1),MapPackets.Mode.FULL,0,List.of(area),List.of());assertEquals(17,frames.size());var mirror=new ClientMapState();for(int i=frames.size()-1;i>=0;i--){mirror.accept(wire(frames.get(i)));if(i>0)assertTrue(mirror.snapshot().areas().isEmpty());}assertEquals(area,mirror.snapshot().areas().get(area.key()));if(holes){assertNull(mirror.snapshot().index().hover(area.dimension(),0,0).localArea());assertNotNull(mirror.snapshot().index().hover(area.dimension(),-1000,0).localArea());}else{assertEquals(1,mirror.snapshot().index().hover(area.dimension(),300,0).localComponent());assertEquals(1,mirror.snapshot().index().queryParts(area.dimension(),MapArea.Kind.LOCAL,new MapArea.Bounds(299,-10,301,10)).size());assertEquals(1,BoundaryPresentation.plan(mirror.snapshot().index(),area.dimension(),new MapArea.Bounds(299,-10,301,10),BoundaryMode.ALL,null).size());}}}
 @Test void oneAboveEachAreaQuotaReportsExactTotalsAndLimits(){var g=GeographyV2Test.geometry(512);g.getAsJsonArray("polygons").get(0).getAsJsonObject().add("outer",GeographyV2Test.points(GeographyV2Test.circle(33,0,0,100)));var error=assertThrows(RuntimeException.class,()->GeographyV2Test.parse(GeographyV2Test.resource(2,"too_many_vertices",true,g)));assertTrue(error.getMessage().contains("too_many_vertices"));assertTrue(error.getMessage().contains("vertices=16385 limit=16384"));var rings=new JsonObject();rings.addProperty("type","multipolygon");var parts=new JsonArray();for(int i=0;i<513;i++)parts.add(GeographyV2Test.part(3,i*300,0,10));rings.add("polygons",parts);error=assertThrows(RuntimeException.class,()->GeographyV2Test.parse(GeographyV2Test.resource(2,"too_many_rings",true,rings)));assertTrue(error.getMessage().contains("vertices=1539"));assertTrue(error.getMessage().contains("rings=513 limit=512"));}
 @Test void globalVertexAndRingQuotasDoNotGrow(){var max=synthetic(false).shape();assertDoesNotThrow(()->GeographyGeometry.catalog(Collections.nCopies(72,max)));assertThrows(RuntimeException.class,()->GeographyGeometry.catalog(Collections.nCopies(73,max)));var triangle=new FeatureGeometry.Part(new FeatureGeometry.Ring(GeographyV2Test.circle(3,0,0,10)),List.of());var rings=FeatureGeometry.multipolygon(Collections.nCopies(512,triangle));assertDoesNotThrow(()->GeographyGeometry.catalog(Collections.nCopies(128,rings)));assertThrows(RuntimeException.class,()->GeographyGeometry.catalog(Collections.nCopies(129,rings)));assertEquals(1179648,GeographyGeometry.CATALOG_VERTICES);assertEquals(65536,GeographyGeometry.CATALOG_RINGS);}
 @Test void external190CandidatesIncludingExactTenBlockersPassNativeParserWithoutCoordinateChanges(){var blocked=new TreeSet<String>();long vertices=0,rings=0;var results=new JsonArray();for(String path:review.refined){var root=JsonParser.parseString(review.raw.get(path));var a=root.getAsJsonObject().getAsJsonArray("local_areas").get(0).getAsJsonObject();var counts=GeographyCapacityBenchmarkTest.counts(a.getAsJsonObject("geometry"));var geo=NpcGeography.parse(List.of(review.macros(),root),Set.of("era_0","era_1"));var actual=geo.localIds().get(a.get("id").getAsString());assertEquals(counts[0],actual.shape().vertexCount(),path);assertEquals(counts[1],actual.shape().ringCount(),path);vertices+=counts[0];rings+=counts[1];if(counts[0]>4096||counts[1]>128)blocked.add(actual.id());var result=new JsonObject();result.addProperty("id",actual.id());result.addProperty("vertices",counts[0]);result.addProperty("rings",counts[1]);result.addProperty("old_capacity_blocker",counts[0]>4096||counts[1]>128);result.addProperty("native_parser","accepted");results.add(result);}assertEquals(BLOCKERS,blocked);assertEquals(147626,vertices);assertEquals(3944,rings);try{var output=GeographyCapacityBenchmarkTest.project().resolve("build/reports/europe-capacity-pipeline.json");java.nio.file.Files.createDirectories(output.getParent());java.nio.file.Files.writeString(output,new GsonBuilder().setPrettyPrinting().create().toJson(results));}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 @Test void fullFrozenProposedCatalogSynchronizesEveryAreaUnderUnchangedBudgets(){var geo=NpcGeography.parse(review.json(review.proposed),Set.of("era_0","era_1"));assertEquals(39,geo.macros().size());assertEquals(1549,geo.locals().size());var known=new DiscoveryLedger.Snapshot(geo.macroIds().keySet(),geo.localIds().keySet(),1);var projected=new MapProjection.Factory(geo,"era_0").project(known);assertEquals(1588,projected.areas().size());var frames=MapPackets.frames(h(1),MapPackets.Mode.FULL,0,projected.areas().values(),List.of());assertTrue(frames.size()<=8192);var mirror=new ClientMapState();for(int i=frames.size()-1;i>=0;i--){mirror.accept(wire(frames.get(i)));if(i>0)assertEquals(0,mirror.snapshot().areas().size());}assertEquals(projected.areas(),mirror.snapshot().areas());assertFalse(mirror.needsResync(),mirror.problem());}
 @Test void externalHiddenGeometryNeverEntersProjectionOrPackets(){var geo=NpcGeography.parse(review.json(review.proposed),Set.of("era_0","era_1"));var projected=new MapProjection.Factory(geo,"era_0").project(new DiscoveryLedger.Snapshot(Set.of(),Set.of("bothnian_coast"),1));assertEquals(1,projected.areas().size());var mirror=new ClientMapState();for(var f:MapPackets.frames(h(1),MapPackets.Mode.FULL,0,projected.areas().values(),List.of()))mirror.accept(wire(f));assertEquals(Set.of(new MapArea.Key(MapArea.Kind.LOCAL,"bothnian_coast")),mirror.snapshot().areas().keySet());assertEquals("",mirror.snapshot().areas().values().iterator().next().parent());}
 @Test void incompleteStaleAndConflictingMaximumFragmentsRetainSafeState(){var area=synthetic(false);var frames=MapPackets.frames(h(2),MapPackets.Mode.FULL,0,List.of(area),List.of());var old=MapArea.decoded(MapArea.Kind.LOCAL,"old","Old",GeographyV2Test.DIM,0,"",GeographyV2Test.circle(4,0,0,100));var mirror=new ClientMapState();MapPackets.frames(h(1),MapPackets.Mode.FULL,0,List.of(old),List.of()).forEach(mirror::accept);mirror.accept(frames.getFirst());assertEquals(old,mirror.snapshot().areas().get(old.key()));var first=frames.getFirst();var c=first.fragments().getFirst();var corrupt=c.data();corrupt[0]^=1;assertFalse(mirror.accept(new MapPackets.Frame(first.header(),first.mode(),first.base(),first.part(),first.parts(),List.of(),List.of(),null,List.of(new MapPackets.Fragment(c.key(),c.index(),c.count(),c.length(),corrupt)))));assertTrue(mirror.needsResync());MapPackets.frames(h(3),MapPackets.Mode.CLEAR,0,List.of(),List.of()).forEach(mirror::accept);frames.forEach(mirror::accept);assertTrue(mirror.snapshot().areas().isEmpty());}
 @Test void malformedLargeGeometryStillRejectsWithoutRepair(){var root=GeographyCapacityBenchmarkTest.fixture(511,32);var outer=root.getAsJsonArray("local_areas").get(0).getAsJsonObject().getAsJsonObject("geometry").getAsJsonArray("outer");var first=outer.get(0);outer.set(0,outer.get(10));outer.set(10,first);assertThrows(RuntimeException.class,()->NpcGeography.parse(List.of(root),Set.of("era_0")));}
 @Test void maximumJsonPassesRealReloadAndOversizedOrInvalidKeepsPreviousIndex()throws Exception{String text=GeographyCapacityBenchmarkTest.fixture(511,32).toString();assertTrue(text.length()>524288);String pretty=new GsonBuilder().setPrettyPrinting().create().toJson(JsonParser.parseString(text));assertTrue(pretty.length()<2097152);new GeographyV2ReloadTest().reload(pretty);var old=NpcContextStore.state();assertEquals(16384,old.data().geography().locals().getFirst().shape().vertexCount());new GeographyV2ReloadTest().reload(text+" ".repeat(2097153));assertSame(old.data(),NpcContextStore.state().data());assertTrue(NpcContextStore.state().error().contains("2MiB"));NpcContextStore.reset();}
 @Test void wireBoundsAndOnlyGeographyMapProtocolAdvance()throws Exception{assertEquals(288*1024,MapPackets.MAX_AREA_BYTES);assertEquals(16*1024,MapPackets.CHUNK_BYTES);assertEquals(48*1024,MapPackets.MAX_BYTES);assertEquals(8192,MapPackets.MAX_PARTS);assertEquals(24*1024*1024,MapPackets.MAX_TRANSFER_BYTES);String map=java.nio.file.Files.readString(GeographyCapacityBenchmarkTest.project().resolve("src/main/java/org/humanjourney/core/geography/map/MapNetwork.java"));assertTrue(map.contains("networkProtocolVersion(3)"));String feature=java.nio.file.Files.readString(GeographyCapacityBenchmarkTest.project().resolve("src/main/java/org/humanjourney/core/mapfeature/FeatureNetwork.java"));assertTrue(feature.contains("networkProtocolVersion(2)"));}
 @Test void maximumCatalogVertexSnapshotPreparationFitsUnchangedStagingAndPartBounds(){var template=synthetic(false);var entries=new ArrayList<MapArea>();for(int i=0;i<72;i++)entries.add(new MapArea(MapArea.Kind.LOCAL,"max_"+i,"Maximum",template.dimension(),0,"",template.shape(),null));var frames=MapPackets.frames(h(1),MapPackets.Mode.FULL,0,entries,List.of());assertEquals(72*17,frames.size());long bytes=frames.stream().flatMap(f->f.fragments().stream()).mapToLong(f->f.data().length).sum();assertTrue(bytes<24*1024*1024);assertTrue(frames.size()<8192);}
}
